// Domain 3 — Describe Azure management and governance. Original flashcards.
let n = 0;
const c = (topic, front, back) => ({ id: `d3-f${String(++n).padStart(3, '0')}`, topic, front, back });

export default [
  c('3.1', 'Name the main factors that affect Azure cost.', 'Resource type and size, consumption, maintenance, geography (region), network traffic, subscription type and Azure Marketplace products.'),
  c('3.1', 'Which data transfer direction is free?', 'Inbound data to Azure. Outbound to the internet and between regions is billed after any free allowance.'),
  c('3.1', 'What does the Azure pricing calculator do?', 'Estimates the monthly cost of Azure services you plan to use. Free, usable without signing in, estimates can be exported and shared.'),
  c('3.1', 'Is the TCO calculator still the tool to compare on-premises with Azure?', 'Treat it as legacy; the old address now redirects. The Azure Migrate business case is the comparable feature that models on-premises versus Azure total cost of ownership.'),
  c('3.1', 'What is Microsoft Cost Management for?', 'Monitoring and controlling actual spend: cost analysis, budgets, alerts, exports and allocation. Not for estimating future services.'),
  c('3.1', 'Does an Azure budget stop resources at the limit?', 'No. It sends alerts at thresholds (actual or forecast) and can trigger an action group. It never stops resources by itself.'),
  c('3.1', 'What is a tag?', 'A name/value pair on a resource, resource group or subscription, used for organization and cost allocation. Metadata only.'),
  c('3.1', 'Are tags inherited from a resource group?', 'No, not by default. Use Azure Policy (for example the modify effect) to copy a tag from the group or subscription.'),
  c('3.1', 'Which role lets you apply tags without access to the resource?', 'Tag Contributor.'),
  c('3.1', 'How do you show each department its own cost?', 'Tag resources by department, then group or filter by that tag in Cost Management cost analysis.'),
  c('3.2', 'RBAC vs Azure Policy in one line?', 'RBAC controls what identities can do. Policy controls what resource configurations are allowed, for everyone including Owners.'),
  c('3.2', 'What is Azure Policy?', 'A service that evaluates resources against rules and reports non-compliance or enforces the rule (deny, modify, deploy).'),
  c('3.2', 'Policy effect: audit.', 'Allows the resource and flags it as non-compliant.'),
  c('3.2', 'Policy effect: deny.', 'Blocks a non-compliant create or update request. Existing resources are not deleted, just reported.'),
  c('3.2', 'Policy effects: modify and append.', 'Add or change properties (such as tags) on create or update. Modify can also remediate existing resources.'),
  c('3.2', 'Policy effect: deployIfNotExists.', 'Deploys a related resource when it is missing (for example an extension or diagnostic setting). Remediation tasks fix existing resources.'),
  c('3.2', 'What is an initiative?', 'A group of policy definitions assigned together to reach a goal, such as a regulatory standard.'),
  c('3.2', 'Which scopes can a policy be assigned to?', 'Management group, subscription or resource group. Child scopes inherit the assignment.'),
  c('3.2', 'Name the two resource lock levels.', 'CanNotDelete (Delete in the portal): read and modify allowed. ReadOnly: read only, no change or delete.'),
  c('3.2', 'Who do resource locks apply to?', 'Every user and role, including Owners. They override RBAC permissions and are inherited by child resources.'),
  c('3.2', 'Which operations do locks restrict?', 'Management-plane (Azure Resource Manager) operations only. Data-plane activity inside a resource is not blocked.'),
  c('3.2', 'Who can create or remove locks by default?', 'Roles with Microsoft.Authorization permissions: Owner and User Access Administrator.'),
  c('3.2', 'What is Microsoft Purview?', 'A family of data governance, risk and compliance solutions: discover and classify data, track lineage, protect it, and assess compliance.'),
  c('3.2', 'Which Purview tool gives a compliance score?', 'Compliance Manager, with improvement actions against regulations and standards.'),
  c('3.3', 'What is Azure Resource Manager?', 'The deployment and management layer. Every tool (portal, CLI, PowerShell, templates) sends requests through it for consistent results.'),
  c('3.3', 'When is the portal the wrong tool?', 'For repeatable or large-scale deployments. It is graphical and manual, so use scripts or infrastructure as code.'),
  c('3.3', 'What is Azure Cloud Shell?', 'A browser-based, pre-authenticated shell with Bash or PowerShell and the Azure CLI and Azure PowerShell preinstalled. Nothing to install.'),
  c('3.3', 'Does Cloud Shell need a storage account?', 'Optional. With storage, $HOME persists in a file share; without it (ephemeral session) files are deleted when the session ends.'),
  c('3.3', 'Azure CLI vs Azure PowerShell?', 'Same capabilities. CLI uses az commands and text/JSON; PowerShell uses Az Verb-Noun cmdlets and objects. Both run locally and in Cloud Shell.'),
  c('3.3', 'What is Azure Arc?', 'Extends Azure management to servers, Kubernetes clusters and data services outside Azure (on-premises, other clouds, edge) by projecting them into ARM.'),
  c('3.3', 'What can you apply to Arc-enabled servers?', 'Azure Policy, RBAC, tags, Azure Monitor and Microsoft Defender for Cloud, like native resources. Arc does not migrate them.'),
  c('3.3', 'What is infrastructure as code?', 'Defining infrastructure in text files deployed by a tool: repeatable, consistent, version-controlled and reviewable.'),
  c('3.3', 'Declarative vs imperative?', 'Declarative (ARM, Bicep, Terraform) states the desired end state and is idempotent. Imperative scripts list steps to run.'),
  c('3.3', 'What is an ARM template?', 'A declarative JSON file defining resources to deploy through Azure Resource Manager, with parameters, variables, resources and outputs.'),
  c('3.3', 'What is Bicep?', 'A Microsoft domain-specific language that compiles to ARM templates. Same capabilities, simpler syntax. Terraform is the third-party alternative.'),
  c('3.4', 'List the five Azure Advisor categories.', 'Reliability, security, performance, cost, operational excellence (the Well-Architected pillars).'),
  c('3.4', 'Does Advisor fix things automatically?', 'No. It gives personalized recommendations and proposed actions; you implement them. It is free.'),
  c('3.4', 'Azure status vs Service Health vs Resource Health?', 'Status: public global page. Service Health: personalized events for your services and regions. Resource Health: one specific resource.'),
  c('3.4', 'Service Health event types?', 'Service issues, planned maintenance, health advisories, and security advisories.'),
  c('3.4', 'What is Azure Monitor?', 'The platform for collecting, analyzing and acting on metrics and logs, with alerts, autoscale and visualizations.'),
  c('3.4', 'What is Log Analytics?', 'The tool and workspace for querying collected logs with Kusto Query Language (KQL).'),
  c('3.4', 'Parts of an Azure Monitor alert rule?', 'Scope, condition (metric, log query or activity log event) and actions through an action group.'),
  c('3.4', 'What is Application Insights?', 'Application performance monitoring in Azure Monitor: requests, failures, exceptions, dependencies, user behavior and availability tests.'),
  c('3.4', 'Metrics vs logs in Azure Monitor?', 'Metrics: lightweight numeric time series for near real-time charts and alerts. Logs: richer records queried in Log Analytics.'),
];
